ALTER PROCEDURE uspFindProducts(
    @min_list_price AS DECIMAL = 0,
    @max_list_price AS DECIMAL = 999999,
    @name AS VARCHAR(max)
)
AS
BEGIN
    SELECT
        product_name,
        list_price
    FROM
        production.products
    WHERE
        list_price >= @min_list_price AND
        list_price <= @max_list_price AND
        product_name LIKE '%' + @name + '%'
    ORDER BY
        list_price;
END;
